self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(async()=>{const cache=await caches.open(CACHE);const base=new URL(self.registration.scope).pathname;const relative='./'+url.pathname.slice(base.length);return await cache.match(relative)||await cache.match(relative.endsWith('/')?relative+'index.html':relative)||await cache.match('./index.html')}));return}const asset=ASSETS.find(p=>new URL(p,self.registration.scope).pathname===url.pathname);if(asset)event.respondWith((async()=>{const cache=await caches.open(CACHE);if(/\.(js|json)$/.test(url.pathname)){try{const response=await fetch(new Request(event.request,{cache:'no-cache'}));if(response.ok)await cache.put(asset,response.clone());return response}catch(error){const hit=await cache.match(asset);if(hit)return hit;throw error}}return await cache.match(asset)||fetch(event.request)})());});
